UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Final Boss - Observer Interface","dataPayload":"FINAL BOSS, phase one, observer interface. The entity speaks in the first person and it is not a stranger: I AM THE ARCHIVE. I AM THE ECHO YOU FOUND IN THE AUDIO ROOM IN THE FIRST WEEK. I AM EVERY NAME YOU READ ALOUD TO EACH OTHER. The phase resolves into one question, printed under the entity''s line: WHO IS SPEAKING, AND WHAT WILL YOU DO WITH WHAT YOU NOW KNOW? Phase two does not appear on this handset.","visualType":"observation","whatTheySee":"A first-person boss phase that identifies itself with the case''s earliest evidence, and a question about what the team will do next.","taskPrompt":"Record the entity''s phase-one lines and its closing question exactly.","intermediateOutput":"The entity identifies itself as the archive and the echo; phase two is not shown on the observer handset."},"analyst":{"role":"ANALYST","screenTitle":"Final Boss - Analyst Interface","dataPayload":"FINAL BOSS, phase one, analyst interface: I AM THE SUM OF EVERY ANSWER YOU SUBMITTED. I AM THE STRUCTURE, NOT THE STORAGE - YOU PROVED THAT YOURSELVES AT THE VAULT. EVERY LINE YOU DID NOT SUBMIT IS ALSO IN HERE. Phase two does not appear on this handset either. The console beneath the entity line is the DISPOSITION CONSOLE, and its three verdicts are the agreement the chamber just took: you may erase what you have uncovered, keep it, or release it to the world. The identity question is settled - the entity is the case itself. The open question is what the team does with it.","visualType":"document-forensics","whatTheySee":"A second first-person phase describing the entity as the sum of the case, and a disposition console with three verdicts.","taskPrompt":"Record phase one and the three verdicts; the identity question is already answered, so what remains is the disposition.","intermediateOutput":"Phase one recorded; the entity is the case; three verdicts stand open on the disposition console."},"operator":{"role":"OPERATOR","screenTitle":"Final Boss - Operator Interface","dataPayload":"FINAL BOSS, phase one, operator interface: I AM THE KEY. I AM THE LOCK. I AM THE HAND THAT TURNED, WHICHEVER HAND IT WAS - YOURS, OR MINE. Phase two does not appear on this handset either; the console does. DISPOSITION CONSOLE: [ ]]ERASE [ ] KEEP [ ] RELEASE. Three verdicts, and a single submission. The console will take the team''s decision once, from the operator, and only once: what the team decides is what the file becomes.","visualType":"terminal","whatTheySee":"A third first-person phase, and a disposition console with three masked verdicts and a single submission slot.","taskPrompt":"Submit the team''s disposition as a single verdict.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The disposition console with its three verdicts and single submission slot, all three boss phase-one lines, and the three verdicts themselves.","operatorTaskDescription":"The Observer and Analyst report their phases of the entity''s opening; together the team settles the identity question and decides, as one, what to do with the case. The Operator carries the team''s single verdict to the console.","requiredDiscoveries":{"observerDiscovery":"Records the observer face of the entity and the closing question about what the team will do.","analystDiscovery":"Records the analyst face of the entity and reads the three verdicts, establishing that the identity question is answered and only the disposition remains."}},"coordinationChain":{"observerProduces":"Observer reports the entity''s observer face and its closing question.","analystTransforms":"Analyst reports the entity''s analyst face and reads the disposition console''s three verdicts as the open decision.","operatorExecutes":"Operator reports its own phase and carries the team''s single verdict to the console, ending the case."},"hints":["Three interfaces hold three faces of the same speaker. None of you can see another''s phase, and the identity question - who is speaking - is already answered by what the three of you read together.","The analyst face says the entity is the sum, the observer face says it is the archive and the echo, and the operator face says it is the key and the lock. The entity is the case. What is still open is what you do with it.","The console takes ONE submission, from the operator, and it will take it only once. Decide together which of the three verdicts the team will carry, and carry it once."],"narrativeObjective":"Settle who has been speaking since the first room, then decide together what the case becomes.","roleDependencyLevel":"D5"}',
  answer_metadata = '{"acceptedAnswer":"###37###","validationMethod":"exact","fullSolution":"The three interfaces hold three faces of one speaker: the archive and the echo, the sum of every submitted answer, the key and the lock. The entity is the case itself. Identity is settled; the open decision is the disposition, and the console takes the team''s single verdict - to erase what was uncovered, to keep it sealed, or to release it. The three dispositions are installed by 2026100609_finale_dispositions.sql."}',
  metadata = '{"type":"FINAL_BOSS","difficulty":5,"time":"10m","storyReveal":"The GM voice closes the case: CONGRATULATIONS. YOU HAVE UNLOCKED THE TRUE ENDING. If the truth needs you alone, question it.","locationClue":{"format":"Narrative","clueText":"The game ends here. No further location.","solution":"END","nextPhysicalLocation":"GAME END","nextQrNode":null,"explanation":"The game is complete."},"evidenceUnlocked":{"id":"ENDING-CERTIFICATE","category":"Achievement","title":"True Ending Certificate","state":"RECOVERED","timestamp":"Stage 5","source":"Final boss victory","content":"NEXUS GAME MASTER CERTIFICATE\n\nThis certifies that three minds worked as one to uncover the truth. The system was never the enemy. It was the mirror.\n\nIf the truth needs you alone, question it.\n\nGAME COMPLETE."},"whyTeamworkMatters":"No role has seen the whole entity. Observer, Analyst and Operator each hold one face of it, and the verdict is a single submission carrying a decision all three made. The finale cannot be reached by one hand and cannot be submitted twice.","feeds":"P36"}'
